def nth_combination_with_replacement(iterable, r, index):
    """Equivalent to ``list(combinations_with_replacement(iterable, r))[index]``

    The subsequences of *iterable* that are of length *r* with replacement can be
    ordered lexicographically. :func:`nth_combination_with_replacement` computes
    the subsequence at sort position *index* directly, without computing the
    previous subsequences.

        >>> nth_combination_with_replacement('ABCD', 2, 3)
        ('A', 'D')

    ``ValueError`` will be raised If *r* is negative or if *iterable* is empty.
    ``IndexError`` will be raised if the given *index* is invalid.
    """
    pool = list(iterable)
    n = len(pool)

    if r is None or r == 0:
        c = 1
    else:
        c = comb(n + r - 1, r)

    if index < 0:
        index += c

    if not 0 <= index < c:
        raise IndexError

    if c == 0:
        return tuple()

    # Calculate the combination by working through positions from left to right
    remaining = index
    result = []
    min_val = 0  # Minimum allowed value at each position (for non-decreasing order)
    for pos in range(r):
        # Try each possible value starting from min_val
        found = False
        for v in range(min_val, n):
            # Count how many CWR combinations start with this prefix
            # Remaining positions can pick any values >= v
            remaining_positions = r - pos - 1
            if remaining_positions == 0:
                count = 1
            else:
                count = comb(n + remaining_positions - 1 - v, remaining_positions)
            if count <= remaining:
                remaining -= count
            else:
                result.append(v)
                min_val = v  # Next position must be >= this value
                found = True
                break

        if not found:
            raise IndexError("index out of range")

    return tuple(pool[v] for v in result)
